import { NotFoundError } from "../domain/errors";
import { ProductSnapshot } from "../domain/product";
import type { ProductRepository } from "../domain/repositories";

export class InventoryService {
  constructor(private readonly products: ProductRepository) {}

  listStock(): ProductSnapshot[] {
    return this.products.findAll().map((p) => p.toSnapshot());
  }

  getStock(productId: string): ProductSnapshot {
    const product = this.products.findById(productId);
    if (!product) throw new NotFoundError(`Product ${productId} not found`);
    return product.toSnapshot();
  }
}

